public int active()
{
    int ret = next active();

    TAMRebateTable  TAMRebateTableLocal = this.cursor();

    TAMRebateTable  rebateTable;
    TAMRebateDeal   rebateDeal;

    rebateTable = this.cursor();
    FormRun formRun = this.formRun();

    select firstonly rebateDeal
        where rebateDeal.RecId == rebateTable.RebateDeal;

    if (rebateDeal.METVolumetricTierDeal == NoYes::Yes)
    {
        if (rebateTable.METTierLineType == METTierLineType::Rate)
        {
            FormControl setupCalculationMethod   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_CalculationMethod));
            setupCalculationMethod.allowEdit(false);

            FormControl setupRebateBasis   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_RebateBasis));
            setupRebateBasis.allowEdit(false);

            if (rebateDeal.State == TAMRebateDealWorkflowState::Draft)
            {
                FormControl setupSourceType   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_SourceType));
                setupSourceType.allowEdit(true);

                FormControl avgBy454Week   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_METAvgBy454Week));
                avgBy454Week.allowEdit(false);

                FormControl rebateFromDate   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateFromDate));
                rebateFromDate.allowEdit(true);

                FormControl rebateToDate   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateToDate));
                rebateToDate.allowEdit(true);
            }
            else
            {
                FormControl setupSourceType   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_SourceType));
                setupSourceType.allowEdit(false);

                FormControl avgBy454Week   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_METAvgBy454Week));
                avgBy454Week.allowEdit(false);

                FormControl rebateFromDate   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateFromDate));
                rebateFromDate.allowEdit(false);

                FormControl rebateToDate   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateToDate));
                rebateToDate.allowEdit(false);
            }

            FormControl setupUnitId   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_UnitId));
            setupUnitId.allowEdit(false);

            FormControl setupMinimumAmount   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_MinimumAmount));
            setupMinimumAmount.allowEdit(false);

            FormControl setupCategoryCategory   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_Category));
            setupCategoryCategory.allowEdit(false);

            FormControl postingRebatePostingId   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Posting_RebatePostingId));
            postingRebatePostingId.allowEdit(false);

            FormControl postingGuaranteePostingId   = this.formRun().design().controlName(formControlStr(TAMRebateDeal,Posting_GuaranteePostingId));
            postingGuaranteePostingId.allowEdit(false);

            FormControl notesDocumentNotes   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Notes_DocumentNotes));
            notesDocumentNotes.allowEdit(false);

            FormControl calculationGroup   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Calculation));
            calculationGroup.allowEdit(false);

            FormControl rebateDate_RebatePer   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebatePer));
            rebateDate_RebatePer.allowEdit(false);

            FormControl rebatePeriodCode   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebatePeriodCode));
            rebatePeriodCode.allowEdit(false);

            FormControl rebateClaimPer   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateClaimPer));
            rebateClaimPer.allowEdit(false);

            FormControl rebateClaimBy   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateClaimBy));
            rebateClaimBy.allowEdit(false);

            FormControl processPosting   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_ProcessPosting));
            processPosting.allowEdit(false);

            FormControl inventoryDimensions   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, LineInventoryDimensions));
            inventoryDimensions.allowEdit(false);

            FormControl     addLineControl    = this.formRun().design().controlName(formControlStr(TAMRebateDeal, AddLine));
            addLineControl.enabled(true);
            FormControl     removeLineControl    = this.formRun().design().controlName(formControlStr(TAMRebateDeal, RemoveLine));
            removeLineControl.enabled(true);

        }
        else if (rebateTable.METTierLineType == METTierLineType::Value)
        {

            if (rebateDeal.State == TAMRebateDealWorkflowState::Draft)
            {
                FormControl setupSourceType   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_SourceType));
                setupSourceType.allowEdit(true);

                FormControl avgBy454Week   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_METAvgBy454Week));
                avgBy454Week.allowEdit(true);

                FormControl rebateFromDate   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateFromDate));
                rebateFromDate.allowEdit(true);

                FormControl rebateToDate   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateToDate));
                rebateToDate.allowEdit(true);
            }
            else
            {
                FormControl setupSourceType   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_SourceType));
                setupSourceType.allowEdit(false);

                FormControl avgBy454Week   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_METAvgBy454Week));
                avgBy454Week.allowEdit(false);

                FormControl rebateFromDate   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateFromDate));
                rebateFromDate.allowEdit(false);

                FormControl rebateToDate   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateToDate));
                rebateToDate.allowEdit(false);
            }

            FormControl setupUnitId   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_UnitId));
            setupUnitId.allowEdit(true);

            FormControl setupMinimumAmount   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_MinimumAmount));
            setupMinimumAmount.allowEdit(true);

            FormControl setupCategoryCategory   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_Category));
            setupCategoryCategory.allowEdit(true);

            FormControl postingRebatePostingId   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Posting_RebatePostingId));
            postingRebatePostingId.allowEdit(true);

            FormControl postingGuaranteePostingId   = this.formRun().design().controlName(formControlStr(TAMRebateDeal,Posting_GuaranteePostingId));
            postingGuaranteePostingId.allowEdit(true);

            FormControl notesDocumentNotes   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Notes_DocumentNotes));
            notesDocumentNotes.allowEdit(true);

            FormControl calculationGroup   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Calculation));
            calculationGroup.allowEdit(true);

            FormControl rebateDate_RebatePer   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebatePer));
            rebateDate_RebatePer.allowEdit(true);

            FormControl rebatePeriodCode   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebatePeriodCode));
            rebatePeriodCode.allowEdit(true);

            FormControl rebateClaimPer   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateClaimPer));
            rebateClaimPer.allowEdit(true);

            FormControl rebateClaimBy   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_RebateClaimBy));
            rebateClaimBy.allowEdit(true);

            FormControl processPosting   = this.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateDate_ProcessPosting));
            processPosting.allowEdit(true);

            FormControl addLineControl = this.formRun().design().controlName(formControlStr(TAMRebateDeal, AddLine));
            addLineControl.enabled(false);

            FormControl removeLineControl = this.formRun().design().controlName(formControlStr(TAMRebateDeal, RemoveLine));
            removeLineControl.enabled(false);

            FormControl setupCalculationMethod = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_CalculationMethod));
            setupCalculationMethod.allowEdit(false);

            FormControl setupRebateBasis = this.formRun().design().controlName(formControlStr(TAMRebateDeal, Setup_RebateBasis));
            setupRebateBasis.allowEdit(false);
        }

        FormDataSource inventDs = formRun.dataSource(formDataSourceStr(TAMRebateDeal, InventDim));
        inventDs.allowEdit(false);
    }

    return ret;
}
